server {
    listen 8080;
    server_name _;

    location /api/ {
        proxy_pass http://api:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    location /admin {
        proxy_pass http://api:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    location /health/ {
        proxy_pass http://api:3000;
    }

    # Browsers revalidate site responses so a switched release is seen on reload.
    location / {
        root /output/current;
        add_header Cache-Control "no-cache" always;
        try_files $uri $uri/ @no_release;
    }

    location @no_release {
        add_header Content-Type text/plain;
        add_header Cache-Control "no-cache" always;
        return 503 "Site build pending\n";
    }
}

files.docker-compose.yml:
services:
  minio:
    build:
      context: ./deploy
      dockerfile: minio.Dockerfile
    command: server /data
    environment:
      MINIO_ROOT_USER: ${LACE_MINIO_ROOT_ACCESS_KEY:?set LACE_MINIO_ROOT_ACCESS_KEY}
      MINIO_ROOT_PASSWORD: ${LACE_MINIO_ROOT_SECRET:?set LACE_MINIO_ROOT_SECRET}
    volumes:
      - minio-data:/data
    networks: [backend]
    healthcheck:
      test: ["CMD-SHELL", "curl --fail http://127.0.0.1:9000/minio/health/live"]
      interval: 10s
      timeout: 3s
      retries: 12
    restart: unless-stopped

  minio-init:
    image: ${LACE_API_IMAGE:?set LACE_API_IMAGE}
    command: ["node", "packages/platform-node/src/minio-init.mjs"]
    environment:
      LACE_MINIO_BUCKET: ${LACE_MINIO_BUCKET:-lace-media}
      LACE_MINIO_ENDPOINT: http://minio:9000
      LACE_MINIO_REGION: ${LACE_MINIO_REGION:-us-east-1}
      LACE_MINIO_ROOT_ACCESS_KEY: ${LACE_MINIO_ROOT_ACCESS_KEY:?set LACE_MINIO_ROOT_ACCESS_KEY}
      LACE_MINIO_ROOT_SECRET: ${LACE_MINIO_ROOT_SECRET:?set LACE_MINIO_ROOT_SECRET}
    depends_on:
      minio: { condition: service_healthy }
    networks: [backend]
    restart: "no"

  migrate:
    image: ${LACE_API_IMAGE:?set LACE_API_IMAGE}
    command: ["node", "packages/platform-node/dist/migrate.js"]
    environment:
      LACE_DATABASE_PATH: /data/lace.sqlite
    volumes:
      - ./.lace/data:/data
    networks: [backend]
    restart: "no"

  api:
    image: ${LACE_API_IMAGE:?set LACE_API_IMAGE}
    environment: &api-environment
      LACE_BUILD_SITE_ID: ${LACE_BUILD_SITE_ID:-main-site}
      LACE_BUILD_SITE_LABEL: ${LACE_BUILD_SITE_LABEL:-Main site}
      LACE_BUILD_SITE_URL: ${LACE_BUILD_SITE_URL:-}
      LACE_TRUSTED_PROXY_CIDRS: ${LACE_TRUSTED_PROXY_CIDRS:-}
      LACE_AUTH_SECRET: ${LACE_AUTH_SECRET:?set LACE_AUTH_SECRET}
      LACE_DATABASE_PATH: /data/lace.sqlite
      LACE_HOST: 0.0.0.0
      LACE_PORT: 3000
      LACE_PUBLIC_BASE_URL: ${LACE_PUBLIC_BASE_URL:?set LACE_PUBLIC_BASE_URL}
      LACE_MINIO_ACCESS_KEY: ${LACE_MINIO_ROOT_ACCESS_KEY:?set LACE_MINIO_ROOT_ACCESS_KEY}
      LACE_MINIO_SECRET_KEY: ${LACE_MINIO_ROOT_SECRET:?set LACE_MINIO_ROOT_SECRET}
      LACE_MINIO_BUCKET: ${LACE_MINIO_BUCKET:-lace-media}
      LACE_MINIO_ENDPOINT: http://minio:9000
      LACE_MINIO_REGION: ${LACE_MINIO_REGION:-us-east-1}
      LACE_MINIO_TIMEOUT_MS: ${LACE_MINIO_TIMEOUT_MS:-5000}
      # Optional transactional email; unset means delivery is not configured.
      LACE_EMAIL_PROVIDER: ${LACE_EMAIL_PROVIDER:-}
      LACE_EMAIL_FROM: ${LACE_EMAIL_FROM:-}
      LACE_EMAIL_TIMEOUT_MS: ${LACE_EMAIL_TIMEOUT_MS:-}
      LACE_SMTP_HOST: ${LACE_SMTP_HOST:-}
      LACE_SMTP_PORT: ${LACE_SMTP_PORT:-}
      LACE_SMTP_SECURITY: ${LACE_SMTP_SECURITY:-}
      LACE_SMTP_USER: ${LACE_SMTP_USER:-}
      LACE_SMTP_PASSWORD: ${LACE_SMTP_PASSWORD:-}
      LACE_RESEND_API_KEY: ${LACE_RESEND_API_KEY:-}
    volumes:
      - ./.lace/data:/data
      - ./lace.config.ts:/opt/lace/workspace/lace.config.ts:ro
    ports:
      - "${LACE_API_PORT:-3000}:3000"
    depends_on:
      migrate: { condition: service_completed_successfully }
      minio-init: { condition: service_completed_successfully }
    networks: [frontend, backend]
    healthcheck:
      test:
        [
          "CMD",
          "node",
          "-e",
          "fetch('http://127.0.0.1:3000/health/ready').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))",
        ]
      interval: 10s
      timeout: 3s
      retries: 12
      start_period: 15s
    restart: unless-stopped

  dispatcher:
    image: ${LACE_API_IMAGE:?set LACE_API_IMAGE}
    command: ["node", "apps/api/dist/dispatcher.js"]
    environment:
      <<: *api-environment
      LACE_BUILDER_URL: http://builder:8788/
      LACE_BUILDER_SECRET: ${LACE_BUILDER_SECRET:?set LACE_BUILDER_SECRET}
    volumes:
      - ./.lace/data:/data
      - ./lace.config.ts:/opt/lace/workspace/lace.config.ts:ro
    depends_on:
      api: { condition: service_healthy }
      builder: { condition: service_healthy }
    networks: [backend]
    healthcheck:
      test: ["CMD", "node", "-e", "process.kill(1,0)"]
      interval: 30s
      timeout: 3s
      retries: 3
    restart: unless-stopped

  static-output-init:
    image: ${LACE_BUILDER_IMAGE:?set LACE_BUILDER_IMAGE}
    user: "0:0"
    entrypoint: ["chown", "node:node", "/output"]
    network_mode: none
    volumes:
      - static-output:/output
    restart: "no"

  builder:
    image: ${LACE_BUILDER_IMAGE:?set LACE_BUILDER_IMAGE}
    environment:
      LACE_BUILD_SITE_DIR: ${LACE_BUILD_SITE_DIR:-site}
      LACE_BUILD_OUTPUT_DIR: ${LACE_BUILD_OUTPUT_DIR:-dist}
      LACE_BUILD_SITE_ID: ${LACE_BUILD_SITE_ID:-main-site}
      LACE_BUILD_SITE_LABEL: ${LACE_BUILD_SITE_LABEL:-Main site}
      LACE_BUILDER_SECRET: ${LACE_BUILDER_SECRET:?set LACE_BUILDER_SECRET}
      LACE_API_BASE_URL: http://api:3000/
      LACE_BUILD_TOKEN: ${LACE_BUILD_TOKEN:-}
      LACE_PUBLIC_BASE_URL: ${LACE_PUBLIC_BASE_URL:?set LACE_PUBLIC_BASE_URL}
      # Optional site output: canonical URLs and the sitemap use the site URL;
      # LACE_SITE_INDEXING=off keeps a staging site out of search engines.
      LACE_BUILD_SITE_URL: ${LACE_BUILD_SITE_URL:-}
      LACE_SITE_INDEXING: ${LACE_SITE_INDEXING:-}
    volumes:
      - type: bind
        source: ${LACE_BUILD_SOURCE_ROOT:-.}
        target: /source
        read_only: true
        bind:
          create_host_path: false
      - static-output:/output
    depends_on:
      api: { condition: service_healthy }
      static-output-init: { condition: service_completed_successfully }
    networks: [backend, build-egress]
    healthcheck:
      test:
        [
          "CMD",
          "node",
          "-e",
          "fetch('http://127.0.0.1:8788/health').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))",
        ]
      interval: 10s
      timeout: 3s
      retries: 12
    restart: unless-stopped

  web:
    image: nginx:1.27.5-alpine
    ports:
      - "${LACE_HTTP_PORT:-8080}:8080"
    volumes:
      - ./deploy/nginx.conf:/etc/nginx/conf.d/default.conf:ro
      - static-output:/output:ro
    depends_on:
      api: { condition: service_healthy }
      static-output-init: { condition: service_completed_successfully }
    networks: [frontend]
    healthcheck:
      test: ["CMD-SHELL", "wget -q -O /dev/null http://127.0.0.1:8080/health/live"]
      interval: 10s
      timeout: 3s
      retries: 12
    restart: unless-stopped

networks:
  frontend:
    driver: bridge
  backend:
    internal: true
  build-egress: {}

volumes:
  minio-data: {}
  static-output: {}

